"""matplotlib.animation — animation stubs for OfflinAi."""

import sys as _sys


_animation_warned = set()

def _animation_getattr_fallback(self, name):
    if name.startswith('_'):
        raise AttributeError(name)
    key = f'{type(self).__name__}.{name}'
    if key not in _animation_warned:
        _animation_warned.add(key)
        try:
            _sys.__stderr__.write(
                f"[mpl-shim] animation.{key}() not implemented — returning None\n")
        except Exception:
            pass
    def _noop(*args, **kwargs): return None
    return _noop


class Animation:
    """Base animation class."""
    __getattr__ = _animation_getattr_fallback

    def __init__(self, fig, event_source=None, blit=False):
        self._fig = fig

    def _build_plotly_frames(self):
        """Run the animation function once per frame, snapshot the figure's
        plotly traces, and attach them as animation frames + a Play/Pause
        control — so plt.show()/write_html render a real, playable animation
        in the preview. Handles the common
        ``def animate(i): plt.cla(); plt.plot(...)`` pattern; pure
        ``line.set_data`` mutation can't be captured (no artist↔trace link).
        Best-effort, idempotent, never raises."""
        if getattr(self, '_frames_built', False):
            return
        self._frames_built = True
        try:
            import plotly.graph_objects as go
            from matplotlib import pyplot as _plt
            func = getattr(self, '_func', None)
            if func is None:
                return
            frames = getattr(self, '_frames', None)
            if frames is None:
                frames = range(int(self._save_count) if getattr(self, '_save_count', None) else 50)
            if isinstance(frames, int):
                frames = range(frames)
            frame_list = list(frames)[:300]            # cap runaway
            if len(frame_list) < 2:
                return
            if getattr(self, '_init_func', None):
                try: self._init_func()
                except Exception: pass
            snaps = []
            for fr in frame_list:
                try:
                    func(fr, *getattr(self, '_fargs', ()))
                except Exception:
                    break
                cur = _plt._current_fig
                if cur is None:
                    continue
                try:
                    snaps.append([t.to_plotly_json() for t in cur.data])
                except Exception:
                    snaps.append([])
            if len([s for s in snaps if s]) < 2:
                return                                  # nothing animated → leave static
            cur = _plt._current_fig
            if cur is None:
                return
            cur.data = []
            for tr in snaps[0]:
                try: cur.add_trace(tr)
                except Exception: pass
            cur.frames = [go.Frame(data=s, name=str(i)) for i, s in enumerate(snaps)]
            dur = getattr(self, '_interval', None) or 80
            cur.update_layout(updatemenus=[dict(
                type='buttons', showactive=False, x=0.02, y=1.12, xanchor='left',
                buttons=[
                    dict(label='▶ Play', method='animate',
                         args=[None, dict(frame=dict(duration=dur, redraw=True),
                                          fromcurrent=True, transition=dict(duration=0))]),
                    dict(label='⏸ Pause', method='animate',
                         args=[[None], dict(frame=dict(duration=0, redraw=False),
                                            mode='immediate')]),
                ])])
        except Exception as e:
            try:
                _sys.__stderr__.write(f"[mpl.animation] frame build skipped: {e}\n")
            except Exception:
                pass

    def save(self, filename, writer=None, fps=None, dpi=None, codec=None,
             bitrate=None, extra_args=None, metadata=None, extra_anim=None,
             savefig_kwargs=None):
        """Save the animation by iterating ``frames`` and rendering each
        as a still image via plotly, then assembling into a GIF (Pillow)
        or HTML (plotly's built-in animation export).

        For .gif / .png / .webp output we use Pillow to write an
        animated image. For .html we use plotly's native animated frame
        export. Other formats fall back to GIF.
        """
        import os
        ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else 'gif'
        frames = self._iter_frames()
        if ext == 'html':
            return self._save_html(filename, fps=fps or 5)
        return self._save_pillow(filename, ext, frames, fps=fps or 5, dpi=dpi)

    def _iter_frames(self):
        """Yield frame data — for ArtistAnimation, the precomputed
        artists; for FuncAnimation, the result of calling ``self._func``
        on each frame value."""
        frames = getattr(self, '_frames', None)
        func = getattr(self, '_func', None)
        if frames is None:
            return []
        if isinstance(frames, int):
            frames = range(frames)
        out = []
        for f in frames:
            if func is not None:
                try: func(f, *getattr(self, '_fargs', ()))
                except Exception: pass
            out.append(f)
        return out

    def _save_pillow(self, filename, ext, frames, *, fps=5, dpi=None):
        """Use Pillow to write a GIF/WebP/animated PNG. Each frame is
        re-rendered by re-invoking the figure's plotly export. If
        kaleido isn't installed we fall back to HTML output beside
        the requested filename.
        """
        try:
            from PIL import Image, ImageDraw
        except ImportError:
            self._save_html(filename, fps=fps)
            return
        import io, sys as _sys
        images = []
        for _ in frames:
            try:
                from matplotlib import pyplot as plt
                buf = io.BytesIO()
                plt.gcf().write_image(buf, format='png',
                                       scale=(dpi or 100) / 100.0)
                buf.seek(0)
                images.append(Image.open(buf).copy())
            except Exception:
                # Kaleido missing — synthesize a placeholder frame.
                im = Image.new('RGB', (800, 600), 'white')
                ImageDraw.Draw(im).text(
                    (20, 20),
                    'matplotlib shim: install kaleido for animated frames',
                    fill='black')
                images.append(im)

        if not images:
            self._save_html(filename, fps=fps)
            return

        duration_ms = int(1000 / max(fps, 1))
        kw = {'save_all': True, 'append_images': images[1:],
               'duration': duration_ms, 'loop': 0,
               'optimize': False}
        try:
            if ext == 'gif':
                images[0].save(filename, format='GIF', **kw)
            elif ext == 'webp':
                images[0].save(filename, format='WebP', **kw)
            elif ext == 'png':
                images[0].save(filename, format='PNG', **kw)
            else:
                images[0].save(filename, format='GIF', **kw)
        except Exception as e:
            print(f'[mpl.animation] save failed: {e}',
                  file=_sys.stderr)
            # Last resort: HTML beside.
            self._save_html(filename, fps=fps)

    def _save_html(self, filename, *, fps=5):
        """Use plotly's animation frame system to emit an interactive
        HTML file."""
        try:
            self._build_plotly_frames()
            from matplotlib import pyplot as plt
            fig = getattr(plt, '_current_fig', None) or plt.gcf()
            fig.write_html(filename, include_plotlyjs=True,
                            auto_play=True)
        except Exception as e:
            print(f'[mpl.animation] html save failed: {e}',
                  file=__import__('sys').stderr)

    def to_html5_video(self, embed_limit=None):
        """Render as an embedded HTML5 ``<video>``. Returns the HTML
        snippet — empty on failure."""
        import io, base64
        try:
            buf = io.BytesIO()
            self.save(buf, fps=5)
        except Exception:
            return ''
        try:
            data = base64.b64encode(buf.getvalue()).decode('ascii')
            return (f'<video controls autoplay loop>'
                     f'<source type="video/mp4" src="data:video/mp4;'
                     f'base64,{data}"></video>')
        except Exception:
            return ''

    def to_jshtml(self, fps=None, embed_frames=True, default_mode=None):
        """Render as plotly's interactive HTML. Equivalent to the
        Matplotlib jsanim format — playback controls plus frame data
        embedded in the page."""
        import io
        try:
            from matplotlib import pyplot as plt
            buf = io.StringIO()
            plt.gcf().write_html(buf, include_plotlyjs=True,
                                  auto_play=True)
            return buf.getvalue()
        except Exception:
            return ''

    def pause(self):
        self._paused = True

    def resume(self):
        self._paused = False


class TimedAnimation(Animation):
    def __init__(self, fig, interval=200, repeat_delay=0, repeat=True, event_source=None, *args, **kwargs):
        super().__init__(fig, event_source)
        self._interval = interval


class FuncAnimation(TimedAnimation):
    """Function-based animation."""

    def __init__(self, fig, func, frames=None, init_func=None, fargs=None,
                 save_count=None, *, cache_frame_data=True, **kwargs):
        super().__init__(fig, **kwargs)
        self._func = func
        self._frames = frames
        self._init_func = init_func
        self._fargs = fargs or ()
        self._save_count = save_count
        # Eagerly capture frames so a subsequent plt.show() renders the
        # animation (with Play/Pause) straight into the preview.
        try:
            self._build_plotly_frames()
        except Exception:
            pass


class ArtistAnimation(TimedAnimation):
    """Artist-based animation."""

    def __init__(self, fig, artists, *args, **kwargs):
        super().__init__(fig, *args, **kwargs)
        self._artists = artists


class PillowWriter:
    """Pillow-backed GIF writer. ``setup`` captures the figure and
    target filename; ``grab_frame`` snapshots the current plotly figure
    into a PNG buffer; ``finish`` assembles them into an animated GIF.
    """

    def __init__(self, fps=5, codec=None, bitrate=None, extra_args=None,
                 metadata=None):
        self.fps = fps
        self._frames = []

    def setup(self, fig, outfile, dpi=None):
        self._fig = fig
        self._outfile = outfile
        self._dpi = dpi or 100

    def grab_frame(self, **savefig_kwargs):
        try:
            from PIL import Image
            import io
            from matplotlib import pyplot as plt
            buf = io.BytesIO()
            plt.gcf().write_image(buf, format='png',
                                   scale=self._dpi / 100.0)
            buf.seek(0)
            self._frames.append(Image.open(buf).copy())
        except Exception:
            pass

    def finish(self):
        if not self._frames: return
        try:
            duration_ms = int(1000 / max(self.fps, 1))
            self._frames[0].save(
                self._outfile, format='GIF',
                save_all=True, append_images=self._frames[1:],
                duration=duration_ms, loop=0,
            )
        except Exception as e:
            print(f'[PillowWriter.finish] {e}',
                  file=__import__('sys').stderr)


class FFMpegWriter:
    """Stub writer for FFMpeg output."""

    def __init__(self, fps=5, codec=None, bitrate=None, extra_args=None,
                  metadata=None):
        self.fps = int(fps)
        self.codec = codec
        self.bitrate = bitrate
        self.extra_args = extra_args
        self.metadata = metadata or {}
        self._frames = []
        self._fig = None
        self._outfile = None
        self._dpi = None

    def setup(self, fig, outfile, dpi=None):
        self._fig = fig
        self._outfile = outfile
        self._dpi = dpi or 100
        self._frames = []

    def grab_frame(self, **savefig_kwargs):
        """Capture the current figure as a PIL Image and append it to
        the in-memory frame buffer."""
        try:
            from PIL import Image
            import io
            buf = io.BytesIO()
            self._fig.savefig(buf, format='png', dpi=self._dpi,
                               **savefig_kwargs)
            buf.seek(0)
            self._frames.append(Image.open(buf).convert('RGBA'))
        except Exception:
            # No PIL or savefig failed — silently drop the frame.
            pass

    def finish(self):
        """Assemble the captured frames into an animated GIF/PNG via
        Pillow's :meth:`Image.save(append_images=…)`."""
        if not self._frames or not self._outfile:
            return
        try:
            self._frames[0].save(
                self._outfile,
                save_all=True,
                append_images=self._frames[1:],
                duration=int(1000 / max(self.fps, 1)),
                loop=0)
        except Exception:
            pass


class HTMLWriter:
    """Writer that emits a self-contained HTML page with a JS-animated
    sequence of <img> elements."""

    def __init__(self, fps=30, codec=None, bitrate=None, extra_args=None,
                  metadata=None, embed_frames=False, default_mode='loop',
                  embed_limit=None):
        self.fps = int(fps)
        self.codec = codec
        self.bitrate = bitrate
        self.extra_args = extra_args
        self.metadata = metadata or {}
        self.embed_frames = embed_frames
        self.default_mode = default_mode
        self.embed_limit = embed_limit
        self._fig = None
        self._outfile = None
        self._dpi = None
        self._frame_b64 = []

    def setup(self, fig, outfile, dpi=None):
        self._fig = fig
        self._outfile = outfile
        self._dpi = dpi or 100
        self._frame_b64 = []

    def grab_frame(self, **savefig_kwargs):
        try:
            import io, base64
            buf = io.BytesIO()
            self._fig.savefig(buf, format='png', dpi=self._dpi,
                               **savefig_kwargs)
            buf.seek(0)
            self._frame_b64.append(base64.b64encode(buf.read()).decode('ascii'))
        except Exception:
            pass

    def finish(self):
        if not self._frame_b64 or not self._outfile:
            return
        delay_ms = int(1000 / max(self.fps, 1))
        # Build a tiny self-contained HTML page.
        imgs = ''.join(
            f'<img class="frame" data-i="{i}" '
            f'src="data:image/png;base64,{b64}" '
            f'style="display:{"block" if i == 0 else "none"};">'
            for i, b64 in enumerate(self._frame_b64))
        html = f"""<!doctype html><html><head>
<meta charset="utf-8"><title>animation</title>
<style>body{{margin:0;background:#000;display:flex;align-items:center;
justify-content:center;min-height:100vh}}</style></head><body>
<div id="anim">{imgs}</div>
<script>
  var i = 0, frames = document.querySelectorAll('.frame');
  setInterval(function(){{
    frames[i].style.display = 'none';
    i = (i + 1) % frames.length;
    frames[i].style.display = 'block';
  }}, {delay_ms});
</script></body></html>"""
        try:
            with open(self._outfile, 'w', encoding='utf-8') as f:
                f.write(html)
        except Exception:
            pass


# Writer registry
writers = {
    'pillow': PillowWriter,
    'ffmpeg': FFMpegWriter,
    'html': HTMLWriter,
}


# ─── Added: missing public Writer classes from upstream animation.py ───
#
# These mirror the pillow/ffmpeg writer surface above. Each provides the
# ``setup`` / ``grab_frame`` / ``finish`` / ``saving`` context-manager API
# upstream consumers expect; the shim doesn't actually drive an encoder,
# so they're no-ops that satisfy isinstance() and ``writers[...]`` lookup.


class _WriterBase:
    """Common surface: registers config, supports the ``saving`` context
    manager, and forwards no-op ``setup``/``grab_frame``/``finish``."""

    fps = 5
    codec = None
    bitrate = -1
    extra_args = None
    metadata = None

    def __init__(self, fps=5, codec=None, bitrate=None, extra_args=None,
                 metadata=None):
        self.fps = fps
        self.codec = codec
        self.bitrate = bitrate
        self.extra_args = extra_args
        self.metadata = metadata or {}
        self._outfile = None

    def setup(self, fig, outfile, dpi=None):
        self._outfile = outfile

    def grab_frame(self, **savefig_kwargs):
        pass

    def finish(self):
        pass

    @classmethod
    def isAvailable(cls):
        # Treat all writers as 'available' so backend-selection helpers
        # downstream don't reject them; the actual encode is a no-op.
        return True

    def saving(self, fig, outfile, dpi=None, *args, **kwargs):
        """Context manager mirroring upstream: enter calls ``setup``,
        exit calls ``finish``. Use as ``with writer.saving(...): ...``."""
        import contextlib
        @contextlib.contextmanager
        def _cm():
            self.setup(fig, outfile, dpi)
            try:
                yield self
            finally:
                self.finish()
        return _cm()


class MovieWriter(_WriterBase):
    """Base class for all writers that produce a movie file from frames.
    Upstream uses subprocess + ffmpeg under the hood; we keep the API
    only."""

    supported_formats = ['rgba']


class FileMovieWriter(MovieWriter):
    """Writer variant that stages individual frame files to a temp
    directory and then concatenates them. Surface-only here."""

    frame_format = 'png'


class FFMpegBase:
    """Mixin holding ffmpeg-specific defaults — used by both the pipe-
    based and file-based ffmpeg writers."""
    exec_key = 'animation.ffmpeg_path'
    codec = 'h264'
    supported_formats = ['rgba']


class FFMpegFileWriter(FFMpegBase, FileMovieWriter):
    """ffmpeg-based writer that stages PNG frames to disk before encoding."""
    pass


class ImageMagickBase:
    exec_key = 'animation.convert_path'


class ImageMagickWriter(ImageMagickBase, MovieWriter):
    """Pipe-based ImageMagick writer. Produces animated GIFs."""
    pass


class ImageMagickFileWriter(ImageMagickBase, FileMovieWriter):
    """ImageMagick writer that stages frames to disk first."""
    pass


class AVConvBase(FFMpegBase):
    """AVConv (libav) writer — used to be ffmpeg's fork. Surface-only."""
    exec_key = 'animation.avconv_path'


class AVConvWriter(AVConvBase, MovieWriter):
    pass


class AVConvFileWriter(AVConvBase, FileMovieWriter):
    pass


class MovieWriterRegistry:
    """Simple writer registry mirroring the upstream class. Provides
    ``register``, ``__getitem__``, ``is_available``, and ``list``."""

    def __init__(self):
        self._registered = {}

    def register(self, name):
        def _decorator(cls):
            self._registered[name] = cls
            return cls
        return _decorator

    def __getitem__(self, name):
        return self._registered[name]

    def __contains__(self, name):
        return name in self._registered

    def is_available(self, name):
        cls = self._registered.get(name)
        return getattr(cls, 'isAvailable', lambda: True)() if cls else False

    def list(self):
        return list(self._registered.keys())


# Extend the legacy writers dict with the new classes so user code that
# does ``writers['ffmpeg_file']`` works.
writers.update({
    'ffmpeg_file': FFMpegFileWriter,
    'imagemagick': ImageMagickWriter,
    'imagemagick_file': ImageMagickFileWriter,
    'avconv': AVConvWriter,
    'avconv_file': AVConvFileWriter,
})

# Singleton instance used by `from matplotlib.animation import writers`.
writers_registry = MovieWriterRegistry()
for _name, _cls in writers.items():
    writers_registry._registered[_name] = _cls


# ─── Added: more public names from upstream animation.py ───────────


class AbstractMovieWriter(_WriterBase):
    """Upstream's :class:`AbstractMovieWriter` is the abstract base of
    every writer; the shim's :class:`_WriterBase` already plays that
    role, but the official name is also exported."""
    pass


def adjusted_figsize(w, h, dpi, n):
    """Round (w, h) so that ``w * dpi`` and ``h * dpi`` are both even
    multiples of ``n``. ffmpeg's H.264 encoder needs even dimensions,
    so upstream uses this to nudge the figure size before encoding.
    """
    wnew = int(round(w * dpi / n)) * n / dpi
    hnew = int(round(h * dpi / n)) * n / dpi
    return wnew, hnew


